"use strict";
// Reel.wav turns rendered audio channels into a 16-bit PCM WAV file, so a reel made outside the engine
// (Remotion, remotion/) can use the house music generated by engine.js (reels/tools/music.mjs).
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");

function loadReel() {
  const window = {};
  vm.runInNewContext(fs.readFileSync(path.join(__dirname, "..", "reels", "engine.js"), "utf8"), { window });
  return window.Reel;
}
const ascii = (b, at, n) => String.fromCharCode(...b.subarray(at, at + n));

test("wav: RIFF/WAVE header for 16-bit stereo at the given sample rate", () => {
  const b = loadReel().wav([new Float32Array(4), new Float32Array(4)], 48000);
  const v = new DataView(b.buffer, b.byteOffset, b.byteLength);
  assert.equal(b.length, 44 + 4 * 2 * 2);
  assert.equal(ascii(b, 0, 4), "RIFF"); assert.equal(v.getUint32(4, true), b.length - 8);
  assert.equal(ascii(b, 8, 4), "WAVE"); assert.equal(ascii(b, 12, 4), "fmt ");
  assert.equal(v.getUint16(20, true), 1, "PCM");
  assert.equal(v.getUint16(22, true), 2, "channels");
  assert.equal(v.getUint32(24, true), 48000, "sample rate");
  assert.equal(v.getUint32(28, true), 48000 * 4, "byte rate");
  assert.equal(v.getUint16(32, true), 4, "block align");
  assert.equal(v.getUint16(34, true), 16, "bits");
  assert.equal(ascii(b, 36, 4), "data"); assert.equal(v.getUint32(40, true), 16);
});

test("wav: samples are interleaved L, R and clipped to ±1", () => {
  const b = loadReel().wav([Float32Array.from([1, -1, 0.5]), Float32Array.from([2, -2, 0])], 8000);
  const v = new DataView(b.buffer, b.byteOffset, b.byteLength), s = i => v.getInt16(44 + i * 2, true);
  assert.deepEqual([s(0), s(1), s(2), s(3), s(4), s(5)], [32767, 32767, -32768, -32768, 16384, 0]);
});
